export async function placeOrder(subtotal: number) {
  const response = await fetch("/api/orders", {
    method: "POST",
    body: JSON.stringify({ subtotal }),
    headers: { "Content-Type": "application/json" },
  });
  const data = await response.json();
  // Intentional shape drift: provider returns orderId, consumer reads receiptId.
  return { id: data.receiptId, total: data.total };
}

export async function loadDynamicOrder(id: string) {
  const url = "/api/orders/" + id;
  const response = await fetch(url);
  const data = await response.json();
  return data.orderId;
}

export async function loadOrder() {
  const response = await fetch("/api/orders/42");
  const data = await response.json();
  return { id: data.orderId, total: data.total };
}

// Static-analysis examples only. None of these handlers are invoked by this lab.
export function unsafePreview(req: any, res: any) {
  const raw = req.query;
  const html = raw;
  res.send(html);
}

export function safePreview(req: any, res: any) {
  const raw = req.query;
  const html = encodeURIComponent(raw);
  res.send(html);
}

export function sendPreview(res: any, html: string) {
  res.send(html);
}

export function wrappedPreview(req: any, res: any) {
  const raw = req.query;
  sendPreview(res, raw);
}

export function callbackPreview(req: any, res: any) {
  const raw = req.query;
  [raw].forEach(value => res.send(value));
}

import express from "express";
import { calculateShipping } from "../services/shipping.ts";

const app = express();

export function createOrder(req: any, res: any) {
  const subtotal = Number(req.body.subtotal);
  const total = subtotal + calculateShipping(subtotal, "local");
  return res.json({ orderId: "demo-001", total, status: "confirmed" });
}

app.post("/api/orders", createOrder);
export default app;

